//! Phase 1 gate: frozen-PySCF oracle comparison for S, T, V, dipole
//! matrices and sampled ERIs. Reference data lives in `tests/oracle_data/`
//! (generated by `tools/oracle/gen_integrals.py`, already permuted into the
//! dft-rs AO ordering).

use dft_rs::basis::{data, MolBasis};
use dft_rs::integrals::{
    dipole_matrices, eri_incore, kinetic_matrix, nuclear_matrix, overlap_matrix, CoulombKernel,
};
use dft_rs::linalg::Matrix;
use dft_rs::system::Molecule;

const TOL: f64 = 1e-11;

fn oracle_path(file: &str) -> std::path::PathBuf {
    std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests/oracle_data")
        .join(file)
}

fn read_matrix(file: &str, n: usize) -> Matrix {
    let text = std::fs::read_to_string(oracle_path(file)).unwrap();
    let mut m = Matrix::zeros(n, n);
    for line in text.lines().filter(|l| !l.starts_with('#')) {
        let mut it = line.split(',');
        let i: usize = it.next().unwrap().parse().unwrap();
        let j: usize = it.next().unwrap().parse().unwrap();
        let v: f64 = it.next().unwrap().trim().parse().unwrap();
        m[(i, j)] = v;
    }
    m
}

fn read_eri_samples(file: &str) -> Vec<(usize, usize, usize, usize, f64)> {
    let text = std::fs::read_to_string(oracle_path(file)).unwrap();
    text.lines()
        .filter(|l| !l.starts_with('#'))
        .map(|line| {
            let mut it = line.split(',');
            let i: usize = it.next().unwrap().parse().unwrap();
            let j: usize = it.next().unwrap().parse().unwrap();
            let k: usize = it.next().unwrap().parse().unwrap();
            let l: usize = it.next().unwrap().parse().unwrap();
            let v: f64 = it.next().unwrap().trim().parse().unwrap();
            (i, j, k, l, v)
        })
        .collect()
}

// Geometries are exact BOHR literals shared verbatim with the oracle
// generator (tools/oracle/gen_integrals.py) so no unit-conversion constant
// enters the comparison.
fn h2o() -> Molecule {
    use dft_rs::math::Vec3;
    use dft_rs::system::Atom;
    Molecule::new(vec![
        Atom {
            z: 8,
            position: Vec3::new(0.0, 0.0, 0.2217),
        },
        Atom {
            z: 1,
            position: Vec3::new(0.0, 1.4309, -0.8867),
        },
        Atom {
            z: 1,
            position: Vec3::new(0.0, -1.4309, -0.8867),
        },
    ])
}

fn ch4() -> Molecule {
    use dft_rs::math::Vec3;
    use dft_rs::system::Atom;
    Molecule::new(vec![
        Atom {
            z: 6,
            position: Vec3::new(0.0, 0.0, 0.0),
        },
        Atom {
            z: 1,
            position: Vec3::new(1.1860, 1.1860, 1.1860),
        },
        Atom {
            z: 1,
            position: Vec3::new(1.1860, -1.1860, -1.1860),
        },
        Atom {
            z: 1,
            position: Vec3::new(-1.1860, 1.1860, -1.1860),
        },
        Atom {
            z: 1,
            position: Vec3::new(-1.1860, -1.1860, 1.1860),
        },
    ])
}

fn check_case(case: &str, mol: &Molecule, basis_name: &str) {
    let set = data::load(basis_name).unwrap();
    let mb = MolBasis::build(mol, &set).unwrap();
    let n = mb.nao_sph;

    let checks = [
        ("s", overlap_matrix(&mb)),
        ("t", kinetic_matrix(&mb)),
        ("v", nuclear_matrix(&mb, mol, None)),
    ];
    for (label, ours) in checks {
        let reference = read_matrix(&format!("{case}_{label}.csv"), n);
        let diff = ours.max_abs_diff(&reference);
        assert!(
            diff < TOL,
            "{case} {label}: max |Δ| = {diff:.3e} exceeds {TOL:.0e}"
        );
    }
    let dips = dipole_matrices(&mb, dft_rs::math::Vec3::zero());
    for (axis, label) in ["dipx", "dipy", "dipz"].iter().enumerate() {
        let reference = read_matrix(&format!("{case}_{label}.csv"), n);
        let diff = dips[axis].max_abs_diff(&reference);
        assert!(
            diff < TOL,
            "{case} {label}: max |Δ| = {diff:.3e} exceeds {TOL:.0e}"
        );
    }

    let eri = eri_incore(&mb, CoulombKernel::Coulomb, 512).unwrap();
    for (i, j, k, l, want) in read_eri_samples(&format!("{case}_eri.csv")) {
        let got = eri.get(i, j, k, l);
        assert!(
            (got - want).abs() < TOL,
            "{case} ({i}{j}|{k}{l}): {got} vs oracle {want}"
        );
    }
}

#[test]
fn h2o_sto3g_matches_pyscf() {
    check_case("h2o_sto3g", &h2o(), "sto-3g");
}

/// def2-SVP water exercises d shells and multi-shell contraction layouts.
#[test]
fn h2o_def2svp_matches_pyscf() {
    check_case("h2o_def2svp", &h2o(), "def2-svp");
}

#[test]
fn ch4_sto3g_matches_pyscf() {
    check_case("ch4_sto3g", &ch4(), "sto-3g");
}
